1	// Public corpus runner (DESIGN.md §"Public corpus"): take the top-scoring candidates from
2	// scripts/corpus-find.ts and review them one at a time. A review that throws is recorded and the run
3	// carries on, so one broken public repo cannot end the corpus.
4	//
5	// The review and write effects are injected: this module owns the order and the report layout, the
6	// caller owns the sandbox and the filesystem (see tests/corpus-run.test.ts for the contract).
7	
8	export interface CorpusCandidate {
9	  repo: string;
10	  score: number;
11	}
12	
13	export interface CorpusFailure {
14	  repo: string;
15	  reason: string;
16	}
17	
18	export interface CorpusResult {
19	  done: string[];
20	  failed: CorpusFailure[];
21	}
22	
23	export interface RunCorpusOpts {
24	  candidates: CorpusCandidate[];
25	  top: number;
26	  review: (repo: string) => Promise<unknown>;
27	  write: (path: string, data: unknown) => Promise<void>;
28	}
29	
30	/** `owner/name` becomes `owner__name` under reports/corpus (the layout corpus-find.ts already writes). */
31	export const slugifyRepo = (repo: string): string => repo.replace(/\//g, "__");
32	
33	export const reviewPath = (repo: string): string => `reports/corpus/${slugifyRepo(repo)}/review.json`;
34	
35	export const INDEX_PATH = "reports/corpus/index.json";
36	
37	/** Highest score first; equal scores are ordered by repo name so the pick is deterministic. */
38	export function rankCorpus(candidates: CorpusCandidate[], top: number): CorpusCandidate[] {
39	  const limit = Math.max(0, Math.floor(top));
40	  return [...candidates]
41	    .sort((a, b) => b.score - a.score || a.repo.localeCompare(b.repo))
42	    .slice(0, limit);
43	}
44	
45	/** Review the top `top` candidates sequentially. Writes each success, then the index, and returns it. */
46	export async function runCorpus(opts: RunCorpusOpts): Promise<CorpusResult> {
47	  const done: string[] = [];
48	  const failed: CorpusFailure[] = [];
49	  for (const { repo } of rankCorpus(opts.candidates, opts.top)) {
50	    try {
51	      const report = await opts.review(repo);
52	      // Write only on success: a failed repo has no review to publish, but stays in the index.
53	      await opts.write(reviewPath(repo), report);
54	      done.push(repo);
55	    } catch (err) {
56	      failed.push({ repo, reason: err instanceof Error ? err.message : String(err) });
57	    }
58	  }
59	  const index: CorpusResult = { done, failed };
60	  await opts.write(INDEX_PATH, index);
61	  return index;
62	}
