22	export function buildCorpusTable(reviews: CorpusReview[]): CorpusTable {
23	  const rows = [...reviews].sort(
24	    (a, b) => b.sessions - a.sessions || (a.repo < b.repo ? -1 : a.repo > b.repo ? 1 : 0),
25	  );
26	  const costs = rows.map((r) => r.costUsd).filter((c): c is number => c !== null);
27	  return {
28	    rows,
29	    totals: {
30	      repos: rows.length,
31	      sessions: rows.reduce((s, r) => s + r.sessions, 0),
32	      costUsd: costs.length ? costs.reduce((s, c) => s + c, 0) : null,
33	      replayed: rows.reduce((s, r) => s + r.replayed, 0),
34	      promotions: rows.filter((r) => r.promoted !== null).length,
35	    },
36	  };
37	}
