5	const DATA = join(process.cwd(), "public", "data");
6	
7	function readReview(dir: string): Review | null {
8	  const file = join(DATA, dir, "review.json");
9	  if (!existsSync(file)) return null;
10	  try {
11	    return normalize(JSON.parse(readFileSync(file, "utf8")));
12	  } catch {
13	    return null;
14	  }
15	}
