17	/**
18	 * Accepts a review.json as `roster review` writes it. Files that are not reviews (no repo or setups) give null.
19	 * Older files without mature_sessions or cost_per_surviving_change get those filled in; rows with no mature
20	 * session have every rate nulled so the page never shows 0% for a setup that has no scored work.
21	 */
22	function normalize(raw: unknown): Review | null {
23	  if (typeof raw !== "object" || raw === null) return null;
24	  const r = raw as Partial<Review>;
25	  if (typeof r.repo !== "string" || !Array.isArray(r.setups)) return null;
26	  const setups = r.setups.map((s): SetupRow => {
27	    const mature = s.mature_sessions ?? s.sessions;
28	    const young = mature === 0;
29	    return {
30	      ...s,
31	      mature_sessions: mature,
32	      unattended: young ? null : s.unattended,
33	      survival: young ? null : s.survival,
34	      reverted: young ? null : s.reverted,
35	      rework_human: young ? null : s.rework_human,
36	      cost_per_surviving_change: s.cost_per_surviving_change ?? null,
37	    };
38	  });
39	  return { ...(r as Review), setups };
40	}
41	
42	/** True for a setup with no mature session: its rates are null and should read "too young", not 0%. */
43	export const isTooYoung = (s: SetupRow) => s.mature_sessions === 0;
44	
45	/** Slug dirs tried in order: "_sample", "owner__repo", "owner-repo", "owner/repo". */
46	function candidates(owner: string, repo: string): string[] {
47	  const list = [`${owner}__${repo}`, `${owner}-${repo}`, join(owner, repo)];
48	  if (owner === "_sample" && repo === "_sample") list.unshift("_sample");
49	  return list;
50	}
51	
52	export function loadReview(owner: string, repo: string): Review | null {
53	  for (const c of candidates(owner, repo)) {
54	    const r = readReview(c);
55	    if (r) return r;
56	  }
57	  return null;
58	}
