60	export function listParams(): { owner: string; repo: string }[] {
61	  if (!existsSync(DATA)) return [];
62	  const out: { owner: string; repo: string }[] = [];
63	  for (const d of readdirSync(DATA, { withFileTypes: true })) {
64	    if (!d.isDirectory()) continue;
65	    const r = readReview(d.name);
66	    if (r) {
67	      const [owner, repo] = r.repo.split("/");
68	      if (owner && repo) out.push({ owner, repo });
69	    }
70	  }
71	  return out;
72	}
