74	/** One row of the /r index. Totals are summed over setups; sessions and mature_sessions are counts. */
75	export interface ReviewSummary {
76	  owner: string;
77	  repo: string;
78	  href: string;
79	  sessions: number;
80	  mature_sessions: number;
81	  setups: number;
82	  label: ReviewLabel;
83	  generated_at: string;
84	}
