86	/**
87	 * Every review under dataDir (default public/data) except the `_sample` layout dir, sorted by sessions
88	 * descending, then repo name. Dirs that hold no readable review are skipped.
89	 */
90	export function listReviews(dataDir: string = DATA): ReviewSummary[] {
91	  if (!existsSync(dataDir)) return [];
92	  const out: ReviewSummary[] = [];
93	  for (const d of readdirSync(dataDir, { withFileTypes: true })) {
94	    if (!d.isDirectory() || d.name === "_sample") continue;
95	    const file = join(dataDir, d.name, "review.json");
96	    if (!existsSync(file)) continue;
97	    let r: Review | null = null;
98	    try {
99	      r = normalize(JSON.parse(readFileSync(file, "utf8")));
100	    } catch {
101	      r = null;
102	    }
103	    if (!r) continue;
104	    const [owner, repo] = r.repo.split("/");
105	    if (!owner || !repo) continue;
106	    out.push({
107	      owner,
108	      repo,
109	      href: `/r/${owner}/${repo}`,
110	      sessions: r.setups.reduce((n, s) => n + s.sessions, 0),
111	      mature_sessions: r.setups.reduce((n, s) => n + s.mature_sessions, 0),
112	      setups: r.setups.length,
113	      label: r.label,
114	      generated_at: r.generated_at,
115	    });
116	  }
117	  return out.sort((a, b) => b.sessions - a.sessions || `${a.owner}/${a.repo}`.localeCompare(`${b.owner}/${b.repo}`));
118	}
