1	// Recomputes the totals in every reports/**/*.json and exits 1 with a diff on any mismatch.
2	// Rules (applied to every object found, at any depth):
3	//   total + by_setup            sum(by_setup) = total
4	//   n + pass + fail + excluded  pass + fail + excluded = n
5	//   cost_total_usd + cost_by_setup  sum(cost_by_setup) = cost_total_usd (within 0.005)
6	//   <k>_pct + <k> + n           <k>_pct = 100 * <k> / n (within 0.1 pt)
7	import { readdirSync, readFileSync, statSync } from "node:fs";
8	import { join } from "node:path";
9	
10	export type Mismatch = { file: string; path: string; rule: string; expected: number; actual: number };
11	
12	const isNum = (v: unknown): v is number => typeof v === "number" && Number.isFinite(v);
13	const isRecord = (v: unknown): v is Record<string, unknown> =>
14	  typeof v === "object" && v !== null && !Array.isArray(v);
15	
16	function sumOf(v: unknown): number | undefined {
17	  const vals = Array.isArray(v) ? v : isRecord(v) ? Object.values(v) : undefined;
18	  if (!vals || vals.length === 0 || !vals.every(isNum)) return undefined;
19	  return vals.reduce((a, b) => a + b, 0);
20	}
21	
22	export function checkReport(file: string, data: unknown): Mismatch[] {
23	  const out: Mismatch[] = [];
24	  const add = (path: string, rule: string, expected: number, actual: number, tol: number) => {
25	    if (Math.abs(expected - actual) > tol) out.push({ file, path, rule, expected, actual });
26	  };
27	  const walk = (node: unknown, path: string) => {
28	    if (Array.isArray(node)) return node.forEach((x, i) => walk(x, `${path}[${i}]`));
29	    if (!isRecord(node)) return;
30	    if (isNum(node.total)) {
31	      const s = sumOf(node.by_setup);
32	      if (s !== undefined) add(`${path}.total`, "sum(by_setup) = total", s, node.total, 1e-9);
33	    }
34	    if (isNum(node.n) && isNum(node.pass) && isNum(node.fail) && isNum(node.excluded)) {
35	      add(`${path}.n`, "pass + fail + excluded = n", node.pass + node.fail + node.excluded, node.n, 1e-9);
36	    }
37	    if (isNum(node.cost_total_usd)) {
38	      const s = sumOf(node.cost_by_setup);
39	      if (s !== undefined) {
40	        add(`${path}.cost_total_usd`, "sum(cost_by_setup) = cost_total_usd", s, node.cost_total_usd, 0.005);
41	      }
42	    }
43	    if (isNum(node.n) && node.n > 0) {
44	      for (const [k, v] of Object.entries(node)) {
45	        if (!k.endsWith("_pct") || !isNum(v)) continue;
46	        const base = k.slice(0, -4);
47	        const count = node[base];
48	        if (isNum(count)) add(`${path}.${k}`, `${k} = 100 * ${base} / n (within 0.1 pt)`, (100 * count) / node.n, v, 0.1);
49	      }
50	    }
51	    for (const [k, v] of Object.entries(node)) walk(v, `${path}.${k}`);
52	  };
53	  walk(data, "$");
54	  return out;
55	}
56	
57	function listJson(dir: string): string[] {
58	  let entries: string[];
59	  try {
60	    entries = readdirSync(dir);
61	  } catch {
62	    return [];
63	  }
64	  return entries.sort().flatMap((e) => {
65	    const p = join(dir, e);
66	    if (statSync(p).isDirectory()) return listJson(p);
67	    return e.endsWith(".json") ? [p] : [];
68	  });
69	}
70	
71	export function sumcheck(reportsDir: string): { files: number; mismatches: Mismatch[] } {
72	  const files = listJson(reportsDir);
73	  const mismatches = files.flatMap((f) => {
74	    try {
75	      return checkReport(f, JSON.parse(readFileSync(f, "utf8")));
76	    } catch (e) {
77	      return [{ file: f, path: "$", rule: `unreadable JSON: ${(e as Error).message}`, expected: 0, actual: 0 }];
78	    }
79	  });
80	  return { files: files.length, mismatches };
81	}
82	
83	export function formatDiff(ms: Mismatch[]): string {
84	  return ms
85	    .map((m) => `${m.file} ${m.path}\n  rule:     ${m.rule}\n- expected: ${m.expected}\n+ actual:   ${m.actual}`)
86	    .join("\n");
87	}
88	
89	if (import.meta.main) {
90	  const dir = process.argv[2] ?? "reports";
91	  const { files, mismatches } = sumcheck(dir);
92	  if (mismatches.length) {
93	    console.error(formatDiff(mismatches));
94	    console.error(`\nsumcheck FAILED: ${mismatches.length} mismatch(es) in ${files} file(s)`);
95	    process.exit(1);
96	  }
97	  console.log(`sumcheck ok: ${files} file(s) in ${dir}`);
98	}
